import 'package:desktop_drop/desktop_drop.dart';import 'package:file_picker/file_picker.dart';import 'package:flutter/material.dart';
class FileSelector extends StatefulWidget{const FileSelector({super.key,required this.value,required this.onChanged,required this.label});final String?value;final ValueChanged<String?>onChanged;final String label;@override State<FileSelector>createState()=>_FileSelectorState();}
class _FileSelectorState extends State<FileSelector>{bool drag=false;Future<void>pick()async{final r=await FilePicker.platform.pickFiles();widget.onChanged(r?.files.single.path);}@override Widget build(BuildContext c)=>DropTarget(onDragEntered:(_)=>setState(()=>drag=true),onDragExited:(_)=>setState(()=>drag=false),onDragDone:(d){setState(()=>drag=false);if(d.files.isNotEmpty)widget.onChanged(d.files.first.path);},child:InkWell(onTap:pick,child:AnimatedContainer(duration:const Duration(milliseconds:150),padding:const EdgeInsets.all(30),decoration:BoxDecoration(color:drag?Theme.of(c).colorScheme.primaryContainer:null,border:Border.all(color:drag?Theme.of(c).colorScheme.primary:Theme.of(c).dividerColor,width:2),borderRadius:BorderRadius.circular(16)),child:Row(children:[const Icon(Icons.file_open,size:42),const SizedBox(width:18),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.label,style:Theme.of(c).textTheme.titleMedium),const SizedBox(height:5),Text(widget.value??'Drop a file here or click to browse',overflow:TextOverflow.ellipsis)]))]))));}}
